const payload = $json.body ?? $json;
const text = JSON.stringify(payload).toLowerCase();
const emergencyTerms = ['no-cool', 'no cool', 'not cooling', 'stopped cooling', 'heat', '86 degrees', 'vulnerable', 'elderly', 'baby'];
const emergencyScore = emergencyTerms.filter((term) => text.includes(term)).length + (payload.vulnerableOccupant ? 2 : 0);
const priority = emergencyScore >= 3 ? 'urgent-callback' : emergencyScore >= 1 ? 'same-day-review' : 'normal-office-follow-up';
return [{ json: { leadId: `DEMO-HVAC-${Date.now()}`, priority, emergencyScore, nextAction: priority === 'urgent-callback' ? 'Create dispatcher callback task now.' : 'Add to service request queue.', lead: payload } }];
